
(function () {
  "use strict";
  const RUI = {
    version: "1.0.0",
    config: {
      emailJsReady: true,
      mapsApiReady: true,
      smoothScroll: true,
      preloader: true,
      cursor: false,
    },
  };
  function initPreloader() {
    const el = document.querySelector(".preloader");
    if (!el) return;
    window.addEventListener("load", () => {
      setTimeout(() => el.classList.add("done"), 400);
    });
  }
  function initTheme() {
    const root = document.documentElement;
    const saved = localStorage.getItem("rui-theme");
    const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    const demoDark = ["demo-01-luxury", "demo-03-sushi", "demo-04-indian", "demo-06-bbq", "demo-07-seafood"];
    const demo = root.getAttribute("data-demo") || "";
    const defaultTheme = saved || (demoDark.includes(demo) ? "dark" : prefersDark ? "dark" : "light");
    applyTheme(defaultTheme);
    document.querySelectorAll("[data-theme-toggle]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const next = root.getAttribute("data-theme") === "dark" ? "light" : "dark";
        applyTheme(next);
        localStorage.setItem("rui-theme", next);
      });
    });
    window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", (e) => {
      if (!localStorage.getItem("rui-theme")) applyTheme(e.matches ? "dark" : "light");
    });
  }
  function applyTheme(theme) {
    document.documentElement.setAttribute("data-theme", theme);
    document.querySelectorAll("[data-theme-toggle]").forEach((btn) => {
      btn.setAttribute("aria-label", theme === "dark" ? "Switch to light theme" : "Switch to dark theme");
      const icon = btn.querySelector("i");
      if (icon) icon.className = theme === "dark" ? "bi bi-sun" : "bi bi-moon-stars";
    });
  }
  function initHeader() {
    const header = document.querySelector(".site-header");
    if (header) {
      const onScroll = () => header.classList.toggle("is-sticky", window.scrollY > 40);
      window.addEventListener("scroll", onScroll, { passive: true });
      onScroll();
    }
    const toggle = document.querySelector(".nav-toggle");
    const mobile = document.querySelector(".mobile-nav");
    const closeBtn = document.querySelector(".mobile-nav-close");
    if (toggle && mobile) {
      toggle.addEventListener("click", () => {
        mobile.classList.add("open");
        toggle.setAttribute("aria-expanded", "true");
        document.body.style.overflow = "hidden";
      });
      const close = () => {
        mobile.classList.remove("open");
        toggle.setAttribute("aria-expanded", "false");
        document.body.style.overflow = "";
      };
      closeBtn?.addEventListener("click", close);
      mobile.querySelectorAll("a").forEach((a) => a.addEventListener("click", close));
    }
    document.querySelectorAll("[data-mega]").forEach((trigger) => {
      const menu = document.querySelector(trigger.getAttribute("data-mega"));
      if (!menu) return;
      trigger.addEventListener("mouseenter", () => menu.classList.add("open"));
      menu.addEventListener("mouseleave", () => menu.classList.remove("open"));
    });
  }
  function initLenis() {
    if (!RUI.config.smoothScroll || typeof Lenis === "undefined") return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const lenis = new Lenis({ duration: 1.1, smoothWheel: true });
    function raf(time) {
      lenis.raf(time);
      requestAnimationFrame(raf);
    }
    requestAnimationFrame(raf);
    window.ruiLenis = lenis;
  }
  function initAnimations() {
    if (typeof AOS !== "undefined") {
      AOS.init({ duration: 800, once: true, offset: 80, easing: "ease-out-cubic" });
    }
    if (typeof gsap !== "undefined" && typeof ScrollTrigger !== "undefined") {
      gsap.registerPlugin(ScrollTrigger);
      document.querySelectorAll("[data-parallax]").forEach((el) => {
        gsap.to(el, {
          yPercent: Number(el.dataset.parallax) || 20,
          ease: "none",
          scrollTrigger: { trigger: el.parentElement || el, scrub: true },
        });
      });
      document.querySelectorAll(".gsap-fade-up").forEach((el) => {
        gsap.from(el, {
          y: 50,
          opacity: 0,
          duration: 1,
          scrollTrigger: { trigger: el, start: "top 85%" },
        });
      });
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) e.target.classList.add("is-inview");
        });
      },
      { threshold: 0.15 }
    );
    document.querySelectorAll(".reveal-up, .reveal-left, .reveal-right").forEach((el) => io.observe(el));
  }
  function initCounters() {
    const els = document.querySelectorAll("[data-count]");
    if (!els.length) return;
    const run = (el) => {
      const end = Number(el.dataset.count) || 0;
      const dur = Number(el.dataset.duration) || 2000;
      if (typeof countUp !== "undefined" && countUp.CountUp) {
        const c = new countUp.CountUp(el, end, { duration: dur / 1000, separator: "," });
        if (!c.error) c.start();
        else animateFallback(el, end, dur);
      } else animateFallback(el, end, dur);
    };
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            run(e.target);
            io.unobserve(e.target);
          }
        });
      },
      { threshold: 0.4 }
    );
    els.forEach((el) => io.observe(el));
  }
  function animateFallback(el, end, dur) {
    const start = performance.now();
    const tick = (now) => {
      const p = Math.min((now - start) / dur, 1);
      el.textContent = Math.floor(end * (1 - Math.pow(1 - p, 3))).toLocaleString();
      if (p < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }
  function initSwipers() {
    if (typeof Swiper === "undefined") return;
    document.querySelectorAll(".hero-swiper").forEach((el) => {
      new Swiper(el, {
        loop: true,
        effect: el.dataset.effect || "fade",
        autoplay: { delay: 5000, disableOnInteraction: false },
        pagination: { el: el.querySelector(".swiper-pagination"), clickable: true },
        navigation: {
          nextEl: el.querySelector(".swiper-button-next"),
          prevEl: el.querySelector(".swiper-button-prev"),
        },
      });
    });
    document.querySelectorAll(".testimonial-swiper").forEach((el) => {
      new Swiper(el, {
        loop: true,
        slidesPerView: 1,
        spaceBetween: 24,
        autoplay: { delay: 4000 },
        breakpoints: { 768: { slidesPerView: 2 }, 1200: { slidesPerView: 3 } },
        pagination: { el: el.querySelector(".swiper-pagination"), clickable: true },
      });
    });
    document.querySelectorAll(".menu-swiper").forEach((el) => {
      new Swiper(el, {
        slidesPerView: 1.2,
        spaceBetween: 16,
        breakpoints: { 576: { slidesPerView: 2 }, 992: { slidesPerView: 3 }, 1200: { slidesPerView: 4 } },
        navigation: {
          nextEl: el.querySelector(".swiper-button-next"),
          prevEl: el.querySelector(".swiper-button-prev"),
        },
      });
    });
  }
  function initGallery() {
    if (typeof GLightbox !== "undefined") {
      GLightbox({ selector: ".glightbox", touchNavigation: true, loop: true });
    }
    if (typeof Isotope !== "undefined") {
      document.querySelectorAll("[data-isotope]").forEach((grid) => {
        const iso = new Isotope(grid, { itemSelector: ".grid-item", layoutMode: "fitRows", percentPosition: true });
        const filters = document.querySelectorAll(grid.dataset.filterNav || "[data-filter]");
        filters.forEach((btn) => {
          btn.addEventListener("click", () => {
            filters.forEach((b) => b.classList.remove("active"));
            btn.classList.add("active");
            iso.arrange({ filter: btn.dataset.filter });
          });
        });
      });
    }
    if (typeof Typed !== "undefined") {
      document.querySelectorAll("[data-typed]").forEach((el) => {
        const strings = (el.dataset.typed || "").split("|");
        new Typed(el, { strings, typeSpeed: 55, backSpeed: 30, loop: true, backDelay: 1800 });
      });
    }
  }
  function initMenuFeatures() {
    const grid = document.querySelector("[data-menu-grid]");
    if (!grid) return;
    const items = [...grid.querySelectorAll("[data-menu-item]")];
    const search = document.querySelector("[data-menu-search]");
    const sort = document.querySelector("[data-menu-sort]");
    const filters = document.querySelectorAll("[data-menu-filter]");
    let activeFilter = "*";
    let query = "";
    let sortBy = "default";
    const apply = () => {
      let visible = items.filter((item) => {
        const cats = (item.dataset.category || "").split(" ");
        const name = (item.dataset.name || item.textContent).toLowerCase();
        const matchFilter = activeFilter === "*" || cats.includes(activeFilter.replace(".", ""));
        const matchSearch = !query || name.includes(query);
        return matchFilter && matchSearch;
      });
      if (sortBy === "price-asc") visible.sort((a, b) => Number(a.dataset.price) - Number(b.dataset.price));
      if (sortBy === "price-desc") visible.sort((a, b) => Number(b.dataset.price) - Number(a.dataset.price));
      if (sortBy === "rating") visible.sort((a, b) => Number(b.dataset.rating) - Number(a.dataset.rating));
      if (sortBy === "name") visible.sort((a, b) => (a.dataset.name || "").localeCompare(b.dataset.name || ""));
      items.forEach((i) => (i.style.display = "none"));
      visible.forEach((i) => {
        i.style.display = "";
        grid.appendChild(i);
      });
    };
    filters.forEach((btn) =>
      btn.addEventListener("click", () => {
        filters.forEach((b) => b.classList.remove("active"));
        btn.classList.add("active");
        activeFilter = btn.dataset.menuFilter;
        apply();
      })
    );
    search?.addEventListener("input", (e) => {
      query = e.target.value.toLowerCase().trim();
      apply();
    });
    sort?.addEventListener("change", (e) => {
      sortBy = e.target.value;
      apply();
    });
  }
  function initReservation() {
    const form = document.querySelector("[data-reservation-form]");
    if (!form) return;
    const guestEl = form.querySelector("[data-guest-count]");
    let guests = 2;
    form.querySelectorAll("[data-guest]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const d = btn.dataset.guest;
        if (d === "inc") guests = Math.min(20, guests + 1);
        if (d === "dec") guests = Math.max(1, guests - 1);
        if (guestEl) guestEl.textContent = guests;
        const hidden = form.querySelector('[name="guests"]');
        if (hidden) hidden.value = guests;
      });
    });
    form.querySelectorAll(".table-seat:not(.taken)").forEach((seat) => {
      seat.addEventListener("click", () => {
        form.querySelectorAll(".table-seat").forEach((s) => s.classList.remove("selected"));
        seat.classList.add("selected");
        const hidden = form.querySelector('[name="table"]');
        if (hidden) hidden.value = seat.dataset.table;
      });
    });
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      if (!validateForm(form)) return;
      const btn = form.querySelector('[type="submit"]');
      const original = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Booking...';
      setTimeout(() => {
        btn.disabled = false;
        btn.innerHTML = original;
        showToast("Reservation confirmed! Check your email.", "success");
        const successUrl = form.dataset.successUrl;
        if (successUrl) window.location.href = successUrl;
      }, 1400);
    });
  }
  function validateForm(form) {
    let ok = true;
    form.querySelectorAll("[required]").forEach((field) => {
      const wrap = field.closest(".form-group") || field.parentElement;
      let err = wrap.querySelector(".form-error");
      if (!err) {
        err = document.createElement("div");
        err.className = "form-error";
        wrap.appendChild(err);
      }
      field.classList.remove("is-invalid");
      err.textContent = "";
      if (!field.value.trim()) {
        ok = false;
        field.classList.add("is-invalid");
        err.textContent = "This field is required.";
      } else if (field.type === "email" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(field.value)) {
        ok = false;
        field.classList.add("is-invalid");
        err.textContent = "Enter a valid email.";
      }
    });
    return ok;
  }
  function initForms() {
    document.querySelectorAll("[data-validate-form]").forEach((form) => {
      form.addEventListener("submit", (e) => {
        e.preventDefault();
        if (!validateForm(form)) return;
        showToast(form.dataset.successMessage || "Message sent successfully!", "success");
        const url = form.dataset.successUrl;
        if (url) setTimeout(() => (window.location.href = url), 800);
        else form.reset();
      });
    });
  }
  function showToast(message, type = "info") {
    let toast = document.querySelector(".toast-rui");
    if (!toast) {
      toast = document.createElement("div");
      toast.className = "toast-rui";
      toast.setAttribute("role", "status");
      document.body.appendChild(toast);
    }
    toast.className = `toast-rui alert-${type}`;
    toast.textContent = message;
    requestAnimationFrame(() => toast.classList.add("show"));
    setTimeout(() => toast.classList.remove("show"), 3200);
  }
  function initMagnetic() {
    document.querySelectorAll(".magnetic").forEach((btn) => {
      btn.addEventListener("mousemove", (e) => {
        const r = btn.getBoundingClientRect();
        const x = e.clientX - r.left - r.width / 2;
        const y = e.clientY - r.top - r.height / 2;
        btn.style.transform = `translate(${x * 0.2}px, ${y * 0.2}px)`;
      });
      btn.addEventListener("mouseleave", () => {
        btn.style.transform = "";
      });
    });
  }
  function initCursor() {
    if (!RUI.config.cursor || window.matchMedia("(pointer: coarse)").matches) return;
    const dot = document.createElement("div");
    const ring = document.createElement("div");
    dot.className = "cursor-dot";
    ring.className = "cursor-ring";
    document.body.append(dot, ring);
    window.addEventListener("mousemove", (e) => {
      dot.style.transform = `translate(${e.clientX - 4}px, ${e.clientY - 4}px)`;
      ring.style.transform = `translate(${e.clientX - 18}px, ${e.clientY - 18}px)`;
    });
  }
  function initTabsAccordion() {
    document.querySelectorAll(".tabs-rui").forEach((tabs) => {
      const btns = tabs.querySelectorAll(".tab-btn");
      const panels = tabs.querySelectorAll("[data-tab-panel]");
      btns.forEach((btn) => {
        btn.addEventListener("click", () => {
          btns.forEach((b) => b.classList.remove("active"));
          btn.classList.add("active");
          panels.forEach((p) => (p.hidden = p.dataset.tabPanel !== btn.dataset.tab));
        });
      });
    });
    document.querySelectorAll(".accordion-rui .accordion-button").forEach((btn) => {
      btn.addEventListener("click", () => {
        const item = btn.closest(".accordion-item");
        const body = item.querySelector(".accordion-body");
        const open = !body.hidden;
        item.parentElement.querySelectorAll(".accordion-body").forEach((b) => (b.hidden = true));
        body.hidden = open;
        btn.setAttribute("aria-expanded", String(!open));
      });
    });
  }
  function initCharts() {
    if (typeof Chart === "undefined") return;
    document.querySelectorAll("[data-chart]").forEach((canvas) => {
      const type = canvas.dataset.chart || "line";
      const labels = (canvas.dataset.labels || "Mon,Tue,Wed,Thu,Fri,Sat,Sun").split(",");
      const data = (canvas.dataset.values || "12,19,8,15,22,30,25").split(",").map(Number);
      new Chart(canvas, {
        type,
        data: {
          labels,
          datasets: [
            {
              label: canvas.dataset.label || "Revenue",
              data,
              borderColor: getComputedStyle(document.documentElement).getPropertyValue("--rui-primary").trim() || "#c9a227",
              backgroundColor: "rgba(201,162,39,0.2)",
              tension: 0.35,
              fill: true,
            },
          ],
        },
        options: {
          responsive: true,
          plugins: { legend: { display: false } },
          scales: { y: { beginAtZero: true, ticks: { color: "#888" } }, x: { ticks: { color: "#888" } } },
        },
      });
    });
  }
  function initQuickView() {
    document.querySelectorAll("[data-quick-view]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const modal = document.querySelector("#foodQuickView");
        if (!modal || typeof bootstrap === "undefined") return;
        const title = btn.dataset.title || "Dish";
        const price = btn.dataset.price || "$0";
        const desc = btn.dataset.desc || "";
        const img = btn.dataset.img || "";
        modal.querySelector(".qv-title").textContent = title;
        modal.querySelector(".qv-price").textContent = price;
        modal.querySelector(".qv-desc").textContent = desc;
        const imgEl = modal.querySelector(".qv-img");
        if (imgEl && img) imgEl.src = img;
        bootstrap.Modal.getOrCreateInstance(modal).show();
      });
    });
  }
  function init() {
    initPreloader();
    initTheme();
    initHeader();
    initLenis();
    initAnimations();
    initCounters();
    initSwipers();
    initGallery();
    initMenuFeatures();
    initReservation();
    initForms();
    initMagnetic();
    initCursor();
    initTabsAccordion();
    initCharts();
    initQuickView();
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
  window.RUI = RUI;
  window.ruiToast = showToast;
})();
